public class RPSBattle {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        int k = sc.nextInt();
        int r = sc.nextInt();
        int s = sc.nextInt();
        int p = sc.nextInt();
        String machine = sc.next();

        char[] moves = machine.toCharArray();
        int total = 0;
        boolean[] used = new boolean[n];

        for (int i = 0; i < n; i++) {
            char bestHand = getWinningHand(moves[i]);
            if (i >= k && bestHand == getWinningHand(moves[i - k]) && used[i - k]) {
                // We cannot use the same hand as i-k, so skip this round
                used[i] = false;
                continue;
            }
            used[i] = true;
            total += getPoints(bestHand, r, s, p);
        }

        System.out.println(total);
    }

    static char getWinningHand(char machineHand) {
        switch (machineHand) {
            case 'r': return 'p'; // paper beats rock
            case 'p': return 's'; // scissors beats paper
            case 's': return 'r'; // rock beats scissors
        }
        return ' ';
    }

    static int getPoints(char hand, int r, int s, int p) {
        switch (hand) {
            case 'r': return r;
            case 's': return s;
            case 'p': return p;
        }
        return 0;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

