public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();
        long R = fs.nextLong();
        long S = fs.nextLong();
        long P = fs.nextLong();
        String T = fs.next();

        char[] opp = T.toCharArray();
        char[] chosen = new char[N];
        long ans = 0;

        for (int i = 0; i < N; i++) {
            char winHand;
            long gain;

            if (opp[i] == 'r') {
                winHand = 'p';
                gain = P;
            } else if (opp[i] == 's') {
                winHand = 'r';
                gain = R;
            } else { // opp[i] == 'p'
                winHand = 's';
                gain = S;
            }

            if (i >= K && chosen[i - K] == winHand) {
                chosen[i] = '-'; // choose a non-winning hand to avoid repetition
            } else {
                chosen[i] = winHand;
                ans += gain;
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

