    vector<int> machine(N);
    for (int i = 0; i < N; i++) {
        if (T[i] == 'r') machine[i] = 0;
        else if (T[i] == 's') machine[i] = 1;
        else machine[i] = 2;
    }

    // Points for beating each machine hand
    // beat r (0) with p (2) -> P points
    // beat s (1) with r (0) -> R points
    // beat p (2) with s (1) -> S points
    vector<int> beatPoints = {P, R, S}; // beatPoints[machine] = points

    // dp[i][j] = max score up to round i (0-indexed) with last hand j (0=r,1=s,2=p)
    // For i < K, no restriction.
    // We'll process in groups of K offset.

    long long ans = 0;
    vector<bool> used(N, false);

    // For each offset mod K, process independently
    for (int start = 0; start < K; start++) {
        vector<int> seq;
        vector<int> idx;
        for (int i = start; i < N; i += K) {
            seq.push_back(machine[i]);
            idx.push_back(i);
        }
        int m = seq.size();
        if (m == 0) continue;

        // dp[hand] = max score up to current position ending with hand
        long long dp[3] = {0, 0, 0};
        long long ndp[3];

        for (int pos = 0; pos < m; pos++) {
            int mach = seq[pos];
            for (int h = 0; h < 3; h++) {
                ndp[h] = 0;
                // previous hand can be any except same if pos > 0
                for (int prev = 0; prev < 3; prev++) {
                    if (pos > 0 && prev == h) continue;
                    ndp[h] = max(ndp[h], dp[prev] + ( (h == (mach + 1) % 3) ? beatPoints[mach] : 0 ));
                }
            }
            // if pos == 0, no restriction, but we already handled it in loop (prev != h condition only when pos>0)
            // Actually for pos==0, we need to allow any hand without restriction
            if (pos == 0) {
                for (int h = 0; h < 3; h++) {
                    ndp[h] = (h == (mach + 1) % 3) ? beatPoints[mach] : 0;
                }
            }
            swap(dp, ndp);
        }

        ans += max({dp[0], dp[1], dp[2]});
    }

    cout << ans << "\n";

    return 0;
}

